#include "CloseToHSL/Core/Virtualization/Compatibility/Frontend/Projection/Events/VmxTrapProjectionMapper.h"
#include "CloseToHSL/Core/Virtualization/Compatibility/Frontend/Retire/VmxOperationKind.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ auto mapper=VmxTrapProjectionMapper::getDefault(); auto request=TrapRequest::ForVmxOperation(VmxOperationKind::VmCall,259,1); auto cont=mapper->Project(NeutralTrapResult::Continue(request)); assert(!cont->ShouldExit && cont->ExitReason==VmExitReason::None); auto trap=mapper->Project(NeutralTrapResult::Trap(request,NeutralTrapResultKind::CompatibilityOperationIntercept)); assert(trap->ShouldExit && trap->ExitReason==VmExitReason::VmCall && trap->ExitQualification->Leaf==0x0404 && trap->ExitQualification->Descriptor==10); auto memory=mapper->Project(NeutralTrapResult::Trap(TrapRequest::ForMemory(0x1000,4,TrapAccessType::Read,1),NeutralTrapResultKind::MemoryIntercept)); assert(memory->ExitReason==VmExitReason::MemoryIntercept && memory->ExitQualification->Descriptor==(0x1000ULL | (4ULL<<16))); assert(mapper->ProjectReason(static_cast<NeutralTrapResultKind>(255))==VmExitReason::SecurityPolicyViolation); }
